const results={everyday:{title:'Meet your everyday match.',body:'<strong>Intel Core Series 3</strong> puts modern essentials and value first. A good starting point when your day is mostly documents, web apps, classes and streaming.',tip:'Before you buy: compare RAM, screen quality, battery tests and the full laptop price.'},creative:{title:'Give your big ideas room.',body:'Start with <strong>Intel Core Ultra Series 3</strong> if video editing, large creative projects or heavy multitasking are regular habits. Its higher-end configurations offer more processing and graphics headroom.',tip:'Check the exact model: Intel Arc graphics are available on select models. RAM and storage also matter for editing.'},gaming:{title:'Make room for your next level.',body:'Explore <strong>Intel Core Ultra Series 3</strong>, especially models with stronger Intel Arc graphics, for more demanding games or supported local AI apps.',tip:'Check game benchmarks and app requirements for the specific laptop. Some workloads need a separate graphics card or more memory.'},mixed:{title:'Let your busiest day decide.',body:'Mostly everyday tasks with occasional light editing? Start with <strong>Core Series 3</strong>. Regularly editing large videos, gaming or running demanding local AI? Explore <strong>Core Ultra Series 3</strong>.',tip:'Compare two actual laptops at your budget. A good display, enough RAM and battery life can matter more than the family name.'}};
document.querySelectorAll('[data-choice]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const r=results[button.dataset.choice];document.querySelector('#result').innerHTML=`<span class="eyebrow">YOUR STARTING POINT</span><h3>${r.title}</h3><p>${r.body}</p><div class="result-tip">${r.tip}</div>`;}));
document.querySelector('#share').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href.split('#')[0]);document.querySelector('#share-status').textContent='Link copied. Pass the clarity on.';}catch{document.querySelector('#share-status').textContent='Copy the link from your browser’s address bar to share this guide.';}});
